// MRSSP Safety Monitor — Separation + Altitude Band Check
const MIN_SEPARATION_SAME_CLASS = 15; // meters lateral
const BATTERY_CRITICAL = 15; // % below which abort is triggered

const vehicles = $input.all().map(i => JSON.parse(i.json));
const violations = [];

// Check altitude bands
for (const v of vehicles) {
  const isA = v.vehicle_id.startsWith('AE-') || v.vehicle_id.startsWith('JT-');
  const alt = v.position?.alt_ft_agl || 0;
  // Class A must be 98–262ft (30–80m), Class B must be 0–98ft (0–30m)
  if (isA && (alt < 90 || alt > 270)) {
    violations.push({ vehicle_id: v.vehicle_id, type: 'ALTITUDE_BAND_VIOLATION', value: alt, threshold: '98–262 ft AGL' });
  }
  if (!isA && alt > 105) {
    violations.push({ vehicle_id: v.vehicle_id, type: 'ALTITUDE_BAND_VIOLATION', value: alt, threshold: '0–98 ft AGL' });
  }
  // Battery critical check
  if ((v.battery_pct || 100) < BATTERY_CRITICAL) {
    violations.push({ vehicle_id: v.vehicle_id, type: 'BATTERY_CRITICAL', value: v.battery_pct, threshold: BATTERY_CRITICAL });
  }
}

if (violations.length === 0) return [];

return violations.map(v => ({ json: { ...v, race_id: vehicles[0]?.race_id, detected_at: new Date().toISOString() } }));
